import{_ as o,r as a,o as p,c as l,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"Определение навигации - October CMS - 3.x","titleTemplate":false,"description":"Пункты меню для управления контентом в панели администрирования.","frontmatter":{"subtitle":"Пункты меню для управления контентом в панели администрирования."},"headers":[{"level":2,"title":"Дополнительная навигация","slug":"дополнительная-навигация","link":"#дополнительная-навигация","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/cms/tailor/navigation.md","filePath":"3.x/ru/cms/tailor/navigation.md"}'),u={name:"3.x/ru/cms/tailor/navigation.md"};function i(k,n,d,g,y,m){const t=a("pre-heading"),e=a("post-heading");return p(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"Определение навигации",-1)),s(e),n[1]||(n[1]=r(`<p>В панели администрирования записи отображаются в пункте меню «Контент», а глобальные записи — в пункте «Настройки» (по умолчанию). Вы можете управлять этим поведением с помощью свойства <strong>navigation</strong> в файле чертежа. Следующий код устанавливает иконку и определяет порядок отображения.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>pencil
    <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">200</span>
</code></pre></div><p>Определения <code>navigation</code> и <code>primaryNavigation</code> поддерживают следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>указывает ключ строки локализации метки меню, обязательно.</td></tr><tr><td><strong>order</strong></td><td>числовой вес при определении порядка отображения.</td></tr><tr><td><strong>parent</strong></td><td>привязывает элемент навигации к родительскому элементу, используя handle чертежа.</td></tr><tr><td><strong>icon</strong></td><td>имя иконки из <a href="./../../element/available-icons.html">коллекции иконок October CMS</a>, необязательно.</td></tr><tr><td><strong>iconSvg</strong></td><td>SVG-иконка для использования вместо стандартной иконки, SVG-иконка должна быть прямоугольной и может поддерживать цвета, необязательно.</td></tr></tbody></table></div><p>Чтобы разместить элемент в области Настроек, установите <strong>parent</strong> в значение <code>settings</code>. Определение <strong>category</strong> может быть строкой или ссылкой на константу настроек, например, <code>CATEGORY_COLLECTIONS</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">parent</span><span class="token punctuation">:</span> settings
    <span class="token key atrule">category</span><span class="token punctuation">:</span> Collections
</code></pre></div><p>Чтобы разместить элемент в области Контента, установите <strong>parent</strong> в значение <code>content</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">parent</span><span class="token punctuation">:</span> content
</code></pre></div><p>Чтобы разместить элемент как элемент основной навигации, необходимо определение <strong>primaryNavigation</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">primaryNavigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Blog
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>copy
    <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">500</span>

<span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Main Menu Item
</code></pre></div><p>Чтобы разместить элемент как элемент вторичной навигации, свойство <strong>parent</strong> должно указывать UUID или handle элемента основной навигации.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">parent</span><span class="token punctuation">:</span> &lt;handle<span class="token punctuation">|</span>uuid<span class="token punctuation">&gt;</span>
</code></pre></div><p>Чтобы отключить вторичную навигацию, определите <strong>primaryNavigation</strong> для одного чертежа без того, чтобы он был родителем для других чертежей.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">primaryNavigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Page
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>magic
    <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">500</span>
</code></pre></div><p>Вы также можете полностью отключить навигацию, установив свойство <strong>navigation</strong> в <code>false</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><h2 id="дополнительная-навигация"><a href="#дополнительная-навигация" class="header-anchor">#</a> Дополнительная навигация</h2><p>Используйте свойство <code>extraNavigation</code> для регистрации дополнительных элементов навигации для включения в чертёж. Значение представляет собой массив, соответствующий определению <code>sideMenu</code>, описанному в <a href="./../../extend/backend/navigation.html">спецификации навигации панели управления</a>. Следующий пример включает секцию и разделитель с помощью пользовательских типов отображения, свойство <code>order</code> используется для упорядочивания элементов.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Authors
    <span class="token key atrule">parent</span><span class="token punctuation">:</span> Blog\\Post
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>user
    <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">230</span>

<span class="token key atrule">extraNavigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">_authors_section</span><span class="token punctuation">:</span>
        <span class="token key atrule">itemType</span><span class="token punctuation">:</span> section
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Authors
        <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">210</span>

    <span class="token key atrule">_authors_ruler</span><span class="token punctuation">:</span>
        <span class="token key atrule">itemType</span><span class="token punctuation">:</span> ruler
        <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">220</span>
</code></pre></div><p>Вы также можете регистрировать ссылки на <a href="./../../extend/system/controllers.html">контроллеры плагинов</a>, указав свойство <code>url</code>. Это свойство должно быть установлено в URL контроллера. Следующий пример ссылается на контроллер <strong>acme/blog/posts</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Authors
    <span class="token comment"># ...</span>

<span class="token key atrule">extraNavigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">testimonials</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Testimonials
        <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">210</span>
        <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>group
        <span class="token key atrule">url</span><span class="token punctuation">:</span> acme/blog/posts
</code></pre></div><p>Для установки контекста навигации внутри контроллера используйте метод <code>setTailorContext</code> фасада <code>BackendMenu</code>. Вы также можете указать <code>uuid</code> чертежа с помощью метода <code>setTailorContextUuid</code>. Метод принимает <code>handle</code> или <code>uuid</code> чертежа (первый аргумент) и ключ, используемый элементом дополнительной навигации (второй аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setTailorContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;testimonials&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setTailorContextUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;edcd102e-0525-4e4d-b07e-633ae6c18db6&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;testimonials&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../extend/backend/navigation.html">Навигация панели управления</a></li></ul></div>`,25))])}const b=o(u,[["render",i]]);export{h as __pageData,b as default};
